using System.Text.RegularExpressions;
using DotNetArch.Core.Config;
using DotNetArch.Core.NetArch;

namespace DotNetArch.Core.Operations;

/// <summary>
/// Reads the <c>dotnet-arch.yml</c> of a service that was not generated by the tool (a service that was only adopted) from what is on disk: the solution
/// file, the Api project, the packages, the Dockerfile and <c>.net-arch/project.yml</c>. Entities and use cases are not guessed: the generators only need
/// to know the shape of the solution, and they record what they generate from then on.
/// </summary>
internal static class ConfigDeriver
{
    private static readonly TimeSpan Timeout = TimeSpan.FromSeconds(1);

    /// <summary>Null when the folder is not a layout v2/v3 solution with an Api project (a flat legacy solution is not described by this file).</summary>
    public static SolutionConfig? Derive(string root)
    {
        root = Path.GetFullPath(root);
        var solution = Directory.EnumerateFiles(root, "*.sln").FirstOrDefault();
        var src = Path.Combine(root, "src");
        if (solution is null || !Directory.Exists(src))
            return null;

        var name = Path.GetFileNameWithoutExtension(solution);
        var api = Directory.EnumerateDirectories(src, "*.Api").FirstOrDefault();
        if (api is null)
            return null;

        var layout = Directory.Exists(Path.Combine(root, "test")) ? SolutionConfig.V3Layout : Directory.Exists(Path.Combine(root, "tests")) ? SolutionConfig.V2Layout : null;
        if (layout is null)
            return null;

        var csprojs = Directory.EnumerateFiles(src, "*.csproj", SearchOption.AllDirectories).Where(f => !IsBuildOutput(f)).ToList();
        var packages = string.Concat(csprojs.Select(File.ReadAllText)) + ReadIfExists(Path.Combine(root, "Directory.Packages.props"));
        var config = new SolutionConfig
        {
            SolutionName = name,
            SolutionPath = root,
            StartupProject = Path.GetFileName(api),
            Layout = layout,
            TargetFramework = Regex.Match(string.Concat(csprojs.Select(File.ReadAllText)), "<TargetFramework>([^<]+)</TargetFramework>", RegexOptions.CultureInvariant, Timeout) is { Success: true } framework ? framework.Groups[1].Value : "net9.0",
            DatabaseProvider = packages.Contains("Npgsql", StringComparison.Ordinal) ? "Postgres" : packages.Contains("SqlServer", StringComparison.Ordinal) ? "SqlServer" : "SQLite",
            ApiStyle = Directory.Exists(Path.Combine(api, "Controllers")) ? "controller" : "fast",
            ApiPort = Regex.Match(ReadIfExists(Path.Combine(api, "Dockerfile")), @"^\s*EXPOSE\s+(\d+)", RegexOptions.Multiline | RegexOptions.CultureInvariant, Timeout) is { Success: true } port ? port.Groups[1].Value : string.Empty,
            // The generators add MCP tools through the tool's own host (Tools/ToolRunner.cs); a hand-written MCP host keeps its own catalog.
            McpEnabled = File.Exists(Path.Combine(src, name + ".Mcp", "Tools", "ToolRunner.cs")),
            CliEnabled = Directory.Exists(Path.Combine(src, name + ".Cli")),
            DockerImage = Kebab(name),
            DockerContainer = Kebab(name),
        };

        var feed = Regex.Match(ReadIfExists(Path.Combine(root, "NuGet.config")), "<add key=\"(?<key>[^\"]+)\" value=\"(?<url>https?://(?!api\\.nuget\\.org)[^\"]+)\"", RegexOptions.CultureInvariant, Timeout);
        if (feed.Success)
        {
            config.NuGetSource = feed.Groups["url"].Value;
            config.NuGetSourceName = feed.Groups["key"].Value;
        }

        foreach (var (area, providers) in NetArchStore.LoadState(root)?.Kits ?? new Dictionary<string, string>())
            config.Kits[area] = providers;
        return config;
    }

    private static bool IsBuildOutput(string path) =>
        path.Contains($"{Path.DirectorySeparatorChar}obj{Path.DirectorySeparatorChar}", StringComparison.Ordinal) || path.Contains($"{Path.DirectorySeparatorChar}bin{Path.DirectorySeparatorChar}", StringComparison.Ordinal);

    private static string ReadIfExists(string path) => File.Exists(path) ? File.ReadAllText(path) : string.Empty;

    private static string Kebab(string name) => Regex.Replace(name, "(?<=[a-z0-9])(?=[A-Z])", "-", RegexOptions.CultureInvariant, Timeout).ToLowerInvariant();
}
